quests[54439] = { id = 54439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crucible of Storms: Relics of Shadow", description = "Your intention to stop de naga attacks was noble, {name}. But de talking dagger tricked you into delivering powerful relics into de hands of our enemies.\n\nNo doubt dese artifacts will be well defended. Gather your allies, {class}, and return to de Crucible of Storms.\n\nDefeat any opponents dat stand in your way. Ensure dese relics cannot be used against de Horde.\n\nAnd if any shadowy weapons ask you to do favors for dem in de future... I suggest you decline.", completion = "I am pleased dat you defeated N'Zoth's minions, {name}. But something tells me de danger is far from over.\n\nRemain on your guard, champion. I fear de Old God will be keeping his eye on you.", objectives = "Stop Uu'nat within the Crucible of Storms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54441] = { id = 54441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taking the Blood Gate", description = "We have our forces spread out throughout Nazmir, but we need to do something that will force Rastakhan into action.\n\nWe must personally march into Zuldazar and take the Blood Gate. This will cause them to throw their full army at us.\n\nAs you can see, we're the only ones left that can assault the Blood Gate.\n\nShaw and Telaamon will stay behind to help the rest of the army move up. \n\nYou and I will ride the battle beast into the Blood Gate and take it by force.", completion = "Excellent. We've decimated the Zandalari front lines and paved the way for our soldiers to move in.\n\nIt's time for us to start our main attack.", objectives = "Ride the battlebeast and defeat the Zandalari army at the Blood Gates.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
