quests[54447] = { id = 54447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shady Character", description = "Your followers tell of a smuggler of wit and guile, who was able to charm them with stories of lands far and wide.\n\nThough it cost a fair sum to retrieve, they managed to obtain a token which when displayed to the smuggler, will allow the bearer to purchase his wares.", progress = "Do you really think you should be talking to me?", completion = "Well alright then, looks like you check out.\n\nYea I got pets, they aren't easy to come by though, so don't expect me to give them away.", objectives = "Deliver the token to the shady character.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
