quests[54483] = { id = 54483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailored Training", objectives = "Well if it isn't the little ray of sunshine!\n\nYou know what could brighten your day even more? New recipes! Take a look at what I have.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54484] = { id = 54484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailored Training", objectives = "{name}, good to see you again. I have some new patterns to show you, when you have de time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54485] = { id = 54485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Dazar'alor", description = "Our naval forces are ready to sail for Zuldazar. By the time we're there, the Horde and Zandalari forces should be in Nazmir.\n\nKeeshan and Kelsey checked on the bombs placed within Zuldazar harbor. They're primed and ready to destroy the Zandalari fleet.\n\nGather any of your allies and prepare to set sail for Zuldazar. \n\nWe will strike down the Zandalari and remove the Horde's most powerful ally from this war.", progress = "We must move, there is no more time.", completion = "We have achieved victory, but at a grave cost. Mekkatorque is dead, frozen within a device from his mech.\n\nLady Jaina is being tended to by our best healers. She is badly wounded, but should survive.\n\nAs for Telaamon... our scouts found his body torn to shreds. Every last soldier sent to Nazmir was killed.\n\nBut we did it. The Zandalari fleet is decimated, and King Rastakhan is dead.\n\nOur war with the Horde is almost over. King Anduin will wish to speak with us soon.", objectives = "Defeat King Rastakhan in the Battle of Dazar'alor raid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54488] = { id = 54488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'aki the Headhunter" }
quests[54494] = { id = 54494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expanding our Influence", description = "As we expand the War Effort on the enemy continent we are finding ideal locations to establish new outposts, and even upgrade our current ones.\n\nOnce secure, these outposts will allow us to utilize a new flight network to quickly and easily navigate the area.", completion = "I have many Scouting Reports and Outpost Upgrades available for you to purchase. These will allow you to unlock new outposts, flight paths and upgrades on both continents.\n\nOnce you have chosen a Scouting Report or Outpost Upgrade, use your Mission Command Table and instruct your troops to complete the mission.", objectives = "Talk to Ransa Greyfeather.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54495] = { id = 54495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expanding our Influence", description = "As we expand the War Effort on the enemy continent we are finding ideal locations to establish new outposts, and even upgrade our current ones.\n\nOnce secure, these outposts will allow us to utilize a new flight network to quickly and easily navigate the area.", completion = "I have many Scouting Reports and Outpost Upgrades available for you to purchase. These will allow you to unlock new outposts, flight paths and upgrades on both continents.\n\nOnce you have chosen a Scouting Report or Outpost Upgrade, use your Mission Command Table and instruct your troops to complete the mission.", objectives = "Talk to Vindicator Jaelaana.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
