quests[54510] = { id = 54510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mischief Managed", description = "Thank you for returning this artifact to us, {name}. Now that we have the Abyssal Scepter, the fleet can advance without fear of the seas being turned against us.\n\nPlease report our success to High Commander Wyrmbane.", completion = "Excellent! The Horde having access to the Abyssal Scepter was a point of concern for us. Now that we've recovered it, not only can we move forward with our final plans, we've once more strengthened our friendship with the Kul Tirans.", objectives = "Report to High Commander Wyrmbane in Boralus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
