quests[54559] = { id = 54559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Free Plumeria!", description = "My poor Plumeria has been captured by an exceptionally brutal villain. He has been overseeing the spread of pestilence along the wharf.\n\nRosaline needs my mechanical expertise in fixing our weapons. Would you free my poor Plumeria and slay the vile knight tormenting her?", completion = "I cannot thank you enough for the timely rescue of my gryphon and for removing the vile monster who was torturing her.", objectives = "Defeat Maurizio Deaththrill and free Plumeria.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
