quests[54574] = { id = 54574, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'tago" }
quests[54576] = { id = 54576, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeregan's Finest", description = "The leaders of the Alliance have agreed to fund an elite gnomish aerial task force.\n\nAnd you have been chosen to lead the test team for the Gnomish Elite Aerial Rangers. I have assembled some of the finest tinkers and soldiers from Gnomeregan, who are now under your command.\n\nThe three of them are already here in New Tinkertown. Introduce yourself and assemble them.", progress = "Speak up, soldier!", completion = "Time to give you all your briefing.", objectives = "Speak with the three members of your G.E.A.R. team.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54577] = { id = 54577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowed Halls and Dusty Cogs", description = "An elite aerial unit wouldn't be complete without the newest innovations in flying machine technology.\n\nThere's just one small problem.\n\nThe innovative new engine we built was left behind when we evacuated Gnomeregan. We need that prototype if we want these bombers to safely get off the ground!", progress = "Did you find the engine?", completion = "Excellent! I've sent Tinkerbow and Autoblast ahead to prepare for the engine for installation.", objectives = "Find the Prototype Arcane Engine within the Engineering Labs of Gnomeregan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54578] = { id = 54578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Branchlord Aldrus" }
quests[54579] = { id = 54579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gnome Behind the Trogg", description = "If I just attach the core of this to the input module here... Amplify the matched frequency here...\n\n<Tinkerbow mumbles a few more things while she attaches the communication device to the console.>\n\nFlip the switch, Commander! Just make sure it's the right one. The left one is the self-destruct switch. Or was that reversed...", progress = "Yes?", completion = "Give me just a second to trace the origin of the signal...", objectives = "Help Tinkerbow get the machine working.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54580] = { id = 54580, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tundra Conundrum", description = "While you were in Gnomeregan, we received a distress signal from Fizzcrank Airstrip in Borean Tundra. This seems like the perfect opportunity to show off what G.E.A.R. can do!\n\nI've sent the rest of your squad ahead. Meet them out there.", completion = "Oh, Commander! We arrived shortly before you. The airmen here just finished explaining the situation.", objectives = "Speak with Cog Captain Winklespring at Fizzcrank Airstrip in Borean Tundra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54581] = { id = 54581, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Now With More Mechanical Fowl", description = "The gnomes here report that troggs came down from the north and started attacking everygnome and everything.\n\nSo now it's our job to fix this situation! And luckily, I have the perfect plan for it. We need to calibrate the bomber's gun, and doing so on the ground is much less risky than up in the air.\n\nGive it a go, Commander!", objectives = "Kill 10 Ironbound Brutes or Scrapthrowers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54582] = { id = 54582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smarter Than Your Average Trogg", description = "<Cog Captain Winklespring's voice springs to life over your personal communication system.>\n\nOne of the recon pilots did a scouting run over the station. She reported that there seems to be a trogg on the top level that is larger and smarter than the others. He's somehow managed to get one of the Defendo-Tanks for the station working in his favor.\n\nTake him out!", progress = "Have you found out anything?", completion = "The big trogg was holding this? I think I have an idea...", objectives = "Kill Krugg the Smart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54583] = { id = 54583, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burning Goliath" }
