quests[54611] = { id = 54611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Champions of Azeroth", description = "A grateful Magni Bronzebeard has requested your presence. He wishes to reward you for your exceptional aid.", completion = "Greetings, Archdruid.\n\nFor some time now you have been a paragon in your efforts to aid Azeroth. My gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of my gratitude. The more you aid Azeroth, the more I can provide you.", objectives = "Speak with Magni Bronzebeard in Silithus for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
