quests[54613] = { id = 54613, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twice-Exiled", description = "Elementals of all sorts are bursting free of their bonds across the Highlands.\n\nReturn them to the primordial chaos from whence they came.", objectives = "Kill 12 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54614] = { id = 54614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Executing Exorcisms", description = "Even in death, the Alliance foolishly clings to Horde territory.\n\nDrive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.", objectives = "Kill 12 Vengeful Ghosts in Stromgarde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54615] = { id = 54615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The League Will Lose", description = "Even with the fall of Stromgarde, the League of Arathor continues to operate in the Highlands.\n\nThe northern farmland will belong to the Horde. Go, and defeat the humans.", objectives = "Kill 12 League of Arathor at Dabyrie's Farmstead.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54616] = { id = 54616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boulderfist Beatdown", description = "If the Boulderfist ogres will not join the Horde, there is no place for them in Arathi.\n\nYou know what must be done.", objectives = "Kill 12 Boulderfist clan ogres in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54617] = { id = 54617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sins of the Syndicate", description = "As if the League of Arathor was not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Horde laborers.\n\nPunish them.", objectives = "Kill 12 Syndicate members at Go'Shek Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54618] = { id = 54618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the 7th Legion", description = "Commanders of the 7th Legion forces have requested your presence.  They wish to reward you for your exceptional efforts.", completion = "Huntmaster, thanks to your efforts against the Horde, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare.", objectives = "Speak with Vindicator Jaelaana at Boralus Harbor in Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54619] = { id = 54619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wiping Out the Witherbark", description = "The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed.\n\nDrive the forest trolls from the Highlands.", objectives = "Kill 12 Witherbark tribe trolls in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54620] = { id = 54620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to The Defilers", description = "Even with the destruction of Undercity, the Defilers continue to combat our hold on the Arathi Highlands.\n\nThe farmland at Go'Shek will belong to the Alliance once more. Go, and defeat the Forsaken.", objectives = "Kill 12 Defilers at Go'Shek Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
