quests[54623] = { id = 54623, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boulderfist Beatdown", description = "The Boulderfist ogres have plagued Arathi since the Second War, and they still remain.\n\nYou know what must be done.", objectives = "Kill 12 Boulderfist clan ogres in Arathi Highlands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
