quests[54628] = { id = 54628, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Storm's Wake", description = "The grateful Storm's Wake forces have requested your presence. They wish to reward you for your continued efforts on their behalf.", completion = "Greetings, Huntmaster.\n\nFor some time now you have been a paragon in your efforts to aid us. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude. The more you aid us, the more we can provide you.", objectives = "Speak with Sister Lilyana at Brennadam in Stormsong Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54629] = { id = 54629, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Proudmoore Admiralty", description = "The grateful leaders of the Proudmoore Admiralty have requested your presence. They wish to reward you for your continued aid to their house.", completion = "Greetings, Highlord.\n\nFor some time now you have been a paragon in your efforts for Boralus and the Proudmoore Admiralty. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude. The more you aid us, the more we can provide you.", objectives = "Speak with Provisioner Fray in Boralus Harbor for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54630] = { id = 54630, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of Talanji's Expedition", description = "Your allies among Talanji's Expedition have requested your presence. They wish to reward you for your continued efforts on their behalf.", completion = "Hello, Archdruid.\n\nFor some time now you've been a paragon in your efforts for de Expedition. Our gratitude goes beyond what mere words of thanks can offer.\n\nTake dese trophies as a token of our appreciation. De more you aid us, de more we can provide you.", objectives = "Speak with Provisioner Lija at the Zul'jan Ruins for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54631] = { id = 54631, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Voldunai", description = "Your allies among the Voldunai have requested your presence. They wish to reward you for your continued efforts on their behalf.", completion = "Greetings, Archdruid.\n\nFor some time now you have been a paragon in your efforts to support the Voldunai. Our gratitude goes beyond anything mere words can define.\n\nTake these trophies as a token of our gratitude. The more you aid us, the more we can provide you.", objectives = "Speak with Hoarder Jena at the Vulpera Hideaway for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54632] = { id = 54632, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Zandalari Empire", description = "The grateful leaders of the Zandalari Empire have requested your presence. They wish to reward you for your exceptional aid.", completion = "Greetings, Farseer.\n\nFor some time now you have been a paragon in your efforts to aid de Zandalari Empire. Our gratitude goes beyond what mere words of thanks can offer.\n\nTake dese trophies as a token of our appreciation. De more you aid us, de more we can provide you.", objectives = "Speak with Natal'hakata in Dazar'Alor for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54635] = { id = 54635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mekkatorque's Battle Plans", description = "So we almost got everythin' we need, except for where that airship went!\n\nMy insurance pals found out where they're hidin' that primo-info. \n\nGo and get me Mekkatorque's battle plans, then we can begin the REALLY fun part!", progress = "You get me that thing yet?", completion = "This is perfect! Let's blow us up that annoying mook.", objectives = "Recover Mekkatorque's Battle Plans", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54636] = { id = 54636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sandbinder Sodir" }
quests[54638] = { id = 54638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beat Up the Drums" }
quests[54639] = { id = 54639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Signal in Storm Peaks", description = "It looks like the signal is being transmitted from Storm Peaks. \n\nTime to put these flying machines to work! I'll keep tracking the signal en route in order to get a cleaner read.", progress = "Need something, Commander?", completion = "I've set up a cloaking device that will cover our current location. We should be safe for now.", objectives = "Fly with your squadron to Storm Peaks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54640] = { id = 54640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomercy!", description = "We need to give Tinkerbow some cover while she figures out our new trajectory.\n\n<The Cog Captain hands you a miniature spider tank.>\n\nIt may not look like much, but this is a fully functional spider tank. You'll just need to de-shrinkify it. Use it to distract the troggs down below by thinning their numbers.", progress = "Give those troggs something to worry about, Captain!", completion = "Glad you found your way here safely, Commander!", objectives = "De-shrinkify the Assault Tank and use it to slay troggs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54641] = { id = 54641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Gnomeregan!", description = "It's time to bring down Sparkspanner, Commander.\n\nJust give me the word, and I'll turn this machine straight towards the Halls of Stone!", progress = "Sparkspanner needs to be defeated, for the sake of all Gnomanity.", completion = "Is everyone alright? Our tinker can set up a Medic Bot if necessary.", objectives = "Enter the Halls of Stone and defeat Telzo Sparkspanner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54642] = { id = 54642, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "G.E.A.R. Up", description = "That was a close one, but we managed to defeat Sparkspanner! Gnomanity and Azeroth are saved from a threat they didn't even know about.\n\nHopefully, that's the last time we'll hear from any of Thermaplugg's old goons.\n\nWe should return to Captain Sparknozzle. He will want a full report.", completion = "At attention, soldier!", objectives = "Return to Captain Tread Sparknozzle in New Tinkertown.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
