quests[54681] = { id = 54681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azerite Caravan" }
quests[54682] = { id = 54682, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Missing Blade", description = "<The echo of the blade Xal'atath lingers before you. Though the consciousness that resided within the dagger is gone, the place it once occupied still resonates with power.\n\nYou sense the weapon now speaks another voice. Another purpose....\n\nYou feel compelled to warn the king that the blade may now reside in the hands of the enemy.>", completion = "<You tell Anduin about Xal'atath and N'Zoth. His expression darkens.>\n\nThis is grim news, champion.\n\nThe Alliance stands on the threshold of victory. If the Banshee Queen has learned of a new weapon, she will use it to keep the war going indefinitely.", objectives = "Inform King Anduin about the absence of Xal'atath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54683] = { id = 54683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Blade", description = "<The blade that was known as Xal'atath rests on the ground before you. Though the consciousness that resided within the dagger is gone, it still resonates with power.\n\nAlmost as if the weapon speaks with another voice. Another purpose....\n\nYou feel a compulsion to bring this artifact to the warchief.>", completion = "<As you present the dagger to Sylvanas, a faint smile curls her lips. For the briefest moment, it seems her eyes darken. A trick of the light, no doubt.>\n\nOnce again, you have proven yourself a worthy champion, {name}. This blade is the compass that will guide us to victory.", objectives = "Bring the Dagger to Warchief Sylvanas Windrunner.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54684] = { id = 54684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcanist Quintril" }
