quests[54703] = { id = 54703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Express Delivery", description = "The Horde appears to have misplaced some of its Azerite. It would be rude of us not to return it, don't you think?\n\nThe most efficient way is for me to teleport it back.\n\nI've enchanted the harpoons in that launcher over there. Fire them onto the Horde ships in the bay. I can use them as beacons to return the Azerite to the Horde... and send its ships on their way.", progress = "Well done, {name}.", completion = "It appears as if the fleet won't be needed for much more than hauling wreckage out of the bay.\n\nThank you for helping me to save my people before more could be killed by the Horde. Our foes are growing bolder. Clearly, we need to strike back. Kul Tiras will fight beside the Alliance when we do.", objectives = "Mark locations on the Horde ships to direct Jaina's spell.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54706] = { id = 54706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Made in Kul Tiras", description = "Are you curious about how the Kul Tirans joined the Alliance? \n\nIt was assumed that Kul Tiras would rejoin the Alliance after everything that was done to stabilize their nation.\n\nLady Jaina Proudmoore wanted to cement the allegiance by building King Anduin a ship worthy of the Kul Tiran navy.\n\nShe wished for help in finding the best shipwright in Kul Tiras, Dorian Atwater. It wouldn't be easy, as Dorian was retired.\n\nIt all began with a trip to see Cyrus in Boralus Harbor...", progress = "Yes?", completion = "I may be able to help you find this shipwright, {name}.", objectives = "Speak to Cyrus in Boralus Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54707] = { id = 54707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siegeotron" }
quests[54708] = { id = 54708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home, Home On the Range", description = "<Cyrus peruses a map.>\n\nHmm... Along the road to Fort Daelin... to the north... somewhere in the Deadwash.\n\n<He points to a section of road on the map.>\n\nI've marked a spot on your map that seems likely. I think that will get you close enough. \n\nI'll report back to the Lord Admiral with what we've learned. Good luck, and I hope our shipwright is willing.", progress = "Now what's this?", completion = "<Dorian takes her time to read over the letter. Her brows steadily rise.>", objectives = "Track down the shipwright in Stormsong Valley and deliver the Lord Admiral's Letter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54709] = { id = 54709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54710] = { id = 54710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
