quests[54712] = { id = 54712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spell Components" }
quests[54719] = { id = 54719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worgen in the Ore Mine" }
quests[54721] = { id = 54721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "I'm Too Old for This Ship", description = "If I understood this correctly, the Lord Admiral of the Kul Tiran navy wants me to come out of retirement specifically to build a ship for the king of Stormwind.\n\nCan't say I've had THAT request before.\n\n<Dorian leans back in her chair for a moment and rubs at her eyes.>\n\nI'm getting too old for this nonsense.\n\n<Dorian heaves a long sigh.>\n\nGo on out back and saddle Hurricane for me while I pack my things. We will meet you at Port Fogtide.\n\nWe're going to need a slip.", progress = "I don't go anywhere without my horse, {name}.", completion = "Well. This complicates things a touch.", objectives = "Saddle Hurricane and meet Dorian Atwater at Port Fogtide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54722] = { id = 54722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Tides" }
quests[54723] = { id = 54723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Covering Our Masts", description = "When I was younger, I hid my ships out of vanity.\n\nI often went through a number of designs before I was satisfied. I didn't want anyone to see that. It might ruin the mystique, I reasoned.\n\nNow... I think it best to hide this ship from the likes of those tentacle-faced creeps. I don't think they intend to let us build unchallenged.\n\nGo into the port and place my wards around the main slip. \n\nYou'll see what they do.", progress = "Did you place the wards?", completion = "That should give us some cover. Hopefully they stay away long enough to finish construction.", objectives = "Place 3 Fog Wards in Port Fogtide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54724] = { id = 54724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Blackwood" }
quests[54725] = { id = 54725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Deep Ones", description = "I've spent my whole life on and around the sea. \n\nUntil very recently I feel like I've always had one foot in the water. I knew there were... things... best left untouched.\n\nNow they're here. In Stormsong Valley. Occupying the slip I need to build your ship.\n\nDo I really need to tell you what to do about it?", progress = "I never thought I would see such things in the flesh. Have you dealt with them?", completion = "All this gives me the shivers, {name}.", objectives = "Slay 12 drowned forces in Port Fogtide.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54726] = { id = 54726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frame Work", description = "Now that I have a slip to work in, I'm going to need lumber.\n\nLots of lumber.\n\nThe only lumber mill that could handle this kind of volume at such short notice would be the Algerson Lumber Yard outside of Boralus.\n\nI know this because I've made this exact request of them before.\n\nI will meet you there. Algerson might need a little persuasion.", completion = "I overestimated Algerson's usefulness here, but don't worry. I have a plan.", objectives = "Meet Dorian Atwater at the Algerson Lumber Yard in Tiragarde Sound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54727] = { id = 54727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Team Carry", description = "Algerson is about as useful as a legless horse. We're going to do this ourselves.\n\nThe mill is overrun with bizarre creatures. I'll handle those. You and these hearty volunteers will need to be the muscle of this operation.\n\nDon't look at me like that, {class}. It's just a little lifting.\n\nOnce we have enough lumber, Sal will meet us for a pick up. Just stay close to me and focus on not dropping my wood, yes?", completion = "Why are you all sweaty?", objectives = "Collect 4 heavy lumber and take it to the drop-off point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54728] = { id = 54728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Lumber is Haunted", description = "I don't much believe in ghosts, or hauntings for that matter.\n\nThat said, there is something wrong with this lumber. I can feel it in my bones. They're achier than normal.\n\nI only know of one group that would know what to do. They're reclusive, but we share a love of nature.\n\nSeek out Thornspeaker Birchgrove in Drustvar. I trust no one else with this.", progress = "There's a deep rend in the balance, and it is centered on you. Curious.", completion = "Ah, I see... this is the source of that wrongness I felt.\n\nThis is troubling indeed, {name}.", objectives = "Seek out Thornspeaker Birchgrove in Gol Koval.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54729] = { id = 54729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bleak Hills", description = "While you are visiting Drustvar, I need you to run another errand for me.\n\nThe Wright family owned a mine up near Corlain. Years past, they supplied all the metal ore I used to build my ships.\n\nI can't imagine they're faring too well, based on what we've seen here.\n\nFind Chelsea Wright, the foreman's daughter, and see what they need to get another ore shipment together.\n\nJust tell her Dorian sent you.", completion = "Boy, am I glad to see you. I thought that beast was going to eat me alive!", objectives = "Find Chelsea Wright at the Bleak Hills Mine in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54730] = { id = 54730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gorak Tul's Influence", description = "Long have the Thornspeakers struggled against such magics. It is a conflict as old as the Drust themselves.\n\nGorak Tul's influence, however, has vastly shifted the balance toward that of decay and death. It corrupts what would be an ordinary curse.\n\nI believe Ulfar can correct this.\n\nGo into Gol Koval. Slay our enemies, destroy their cairns, and collect their magics into this vessel.\n\nWith it, Ulfar may be able to find a way to cleanse your materials.", progress = "Be careful, {name}. Drust magic is older than most things that are, and older than some that were.", completion = "The concentration chills me to my bones, but it will be needed. We must hurry before the corruption can touch you.", objectives = "Fill the Drust Vessel in Gol Koval by killing enemies and destroying cairns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54731] = { id = 54731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Balance in All Things", description = "The confluence of energies around that vessel is truly disturbing. My skin crawls with the wrongness of it.\n\nWe have reached the limit of my ability to help you, {name}.\n\nGo to Ulfar, the High Thornspeaker. Arthur will carry you, if you wish it.\n\nOnly he knows enough about these ancient magics to undo the corruption that taints your materials.\n\nGo quickly. You do not want to hold that vessel longer than you must.", progress = "I sense a terrible power emanating from that vessel, {name}.", completion = "We will take what we have learned here and see what can be done about the rest of Drustvar.\n\nFor now, the Drust Vessel will be of use to you and Dorian.\n\nGive her my regards. She is an ally to the Thornspeakers, always.", objectives = "Speak to Ulfar and cleanse the Filled Drust Vessel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[54732] = { id = 54732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drop It!", description = "You must be the person Dorian sent to collect the ore.\n\nI got a message a short while ago requesting a rather large shipment, which in itself is a feat given the state of this place. I was on my way to our storehouse when that... beast!... cornered me.\n\nIt took my keys. I can't get you that shipment without them. Find out where that mongrel took them and bring them back.\n\nLet it be known I wouldn't do this for anyone else.", progress = "<The Wicker Beast stares blankly at you.>", completion = "<The Wicker Beast sniffs the key.>", objectives = "Retrieve Chelsea Wright's keys.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
